// ===================================================================================
//  매핑 테이블 모음 — "이 값은 어디서 오는가"의 정답은 이 파일 아니면 구글시트 2개뿐이다.
// ===================================================================================
//
//  [1] 구글시트에서 실시간으로 불러오는 것  (시트만 고치면 반영됨, 배포 불필요)
//      · group_content 시트 (core.js의 SHEETS_URLS.group_content)
//          광고그룹 이름 → 인타입 / 캠페인 / 카테고리 / 기기 / 블로그·랜딩주소 / 교체주기
//          → 아래 INTYPE_MAP, GROUP_CONTENT_URLS를 채우고, GROUP_TO_CAMP·CAMP_META를 덮어쓴다
//      · display_intype 시트 (core.js의 SHEETS_URLS.display_intype)
//          인타입 → 매체 / 월 / 영역 / 소재 / 보종  (디스플레이 탭 전용, display.js가 직접 읽는다)
//
//  [2] 이 파일에 코드로 박혀 있는 것  (고치려면 이 파일 수정 + 배포 필요)
//      · GROUP_TO_CAMP  광고그룹 → 캠페인      ← 시트 값이 있으면 시트가 이김 (아래 [1] 참고)
//      · CAMP_META      캠페인 → 보종·기기      ← 시트 값이 있으면 시트가 이김
//      · KW_MAP         광고그룹 → 대표 키워드 목록 (파워컨텐츠 상세 모달)
//      · KW_INTYPE_MAP  인타입 → 보종·매체      (키워드 탭. 네이버/구글/다음 인타입 체계라 거의 안 바뀜)
//      · CAMP_CAT_MAP   캠페인코드 C01~C17 → 보종명 (키워드 탭 네이버/구글/다음 캠페인 분류)
//
//  주의: 캠페인명에 _C## 코드가 없으면 core.js의 guC()가 캠페인명 문자열로 보종을 "추측"한다.
//        추측 규칙은 실비/암/치아/어린이/운전/보장 6개만 커버하므로, 신생아·치매·자동차·저축성·
//        생명·종신·정기·주택화재 캠페인은 코드 없이 올리면 '보험'(C01)으로 잘못 분류된다.
//        → 네이버·구글·다음 캠페인명 모두 _C## 를 붙이는 것을 운영 규칙으로 유지할 것
//          (네이버도 2026년부터 이 코드로 키워드 표의 보종을 가른다).
//
// ===================================================================================

// ===== 인타입 매핑 내장 데이터 =====
let INTYPE_MAP = {};
let GROUP_CONTENT_URLS = {};
// 블로그/랜딩 주소는 자주 안 바뀌므로 30일 캐시 사용 (매일 새로 안 받아옴, "데이터 새로고침" 누르면 강제 갱신)
// 교체주기(renewalStatus 등)는 매일 바뀔 수 있어 daily 캐시 사용 (블로그/랜딩 주소도 같이 매일 갱신되지만
// 파일이 작아 부담 없음 — 시트 하나라 컬럼별로 캐시 주기를 나눌 수는 없음)
async function _loadGroupContentUrls(){
  if(!SHEETS_URLS.group_content) return;
  try{
    let rows = await _getCached('group_content', _TTL_DYNAMIC);
    if(!rows){
      // 이 시트가 응답 없으면 여길 기다리는 거의 모든 탭(파워컨텐츠/키워드/디스플레이/Daily)이
      // 같이 멈추므로 타임아웃을 걸고, 실패해도 빈 매핑으로 계속 진행한다
      const text = await _fetchWithTimeout(SHEETS_URLS.group_content, 8000).then(r=>r.text());
      rows = _pCSV(text) || [];
      await _setCached('group_content', rows);
    }
    const map = {};
    const intypeMap = {};
    rows.forEach(r=>{
      const g = (r['광고그룹 이름']||'').trim();
      if(!g) return;
      map[g] = {
        blog: r['블로그주소']||null, landing: r['랜딩']||null,
        publishedAt: r['publishedAt']||null, renewalDueAt: r['renewalDueAt']||null,
        daysRemaining: r['daysRemaining']||null, renewalStatus: r['renewalStatus']||null,
        groupId: (r['광고그룹 ID']||'').trim()||null
      };
      const it = (r['인타입']||'').trim();
      if(it) intypeMap[g] = it;
      // 캠페인/카테고리/기기도 이 시트에서 관리 (그룹→캠페인, 캠페인→카테고리/기기) —
      // 시트에 값이 채워진 것만 덮어쓰고, 비어있으면 코드에 내장된 기존 값을 그대로 둔다
      const camp = (r['캠페인']||'').trim();
      if(camp) GROUP_TO_CAMP[g] = camp;
      const cat = (r['카테고리']||'').trim();
      const media = (r['기기']||'').trim();
      if(camp && (cat||media)){
        const prev = CAMP_META[camp]||{};
        CAMP_META[camp] = {cat: cat||prev.cat||'기타', media: media||prev.media||'모바일'};
      }
    });
    GROUP_CONTENT_URLS = map;
    INTYPE_MAP = intypeMap;
    // 이 fetch는 renderTable()/분석보다 늦게 끝날 수 있어, 이미 그려진 테이블을 새로고침해준다
    if(typeof resultData!=='undefined' && resultData.length) renderTable();
  }catch(e){ console.error('소재/인타입 매핑 로드 실패', e); }
}

// 여러 부트스트랩 경로(초기 로드, 알림체크, 탭 전환 등)가 _apiAnalyze를 부르기 전에
// INTYPE_MAP이 구글시트에서 준비될 때까지 기다리도록 공유하는 Promise (한 번만 fetch됨)
let _intypeMapReadyPromise = null;
function _ensureIntypeMapLoaded(){
  if(!_intypeMapReadyPromise) _intypeMapReadyPromise = _loadGroupContentUrls();
  return _intypeMapReadyPromise;
}

// 교체주기 임박 배지: due_15d/due_30d 등 "due_N d" 형식이면 남은 일수에 따라 빨강(<=15일)/노랑(<=30일), normal이면 초록
function _renewalBadge(group){
  const info = GROUP_CONTENT_URLS[group];
  if(!info || !info.renewalStatus) return '';
  const dLabel = info.daysRemaining ? `D-${info.daysRemaining}` : '';
  const m = info.renewalStatus.match(/^due_(\d+)d$/);
  if(m){
    const days = parseInt(m[1]);
    const color = days<=15 ? '#dc2626' : '#f59e0b';
    return `<span title="소재 교체 임박 ${dLabel}" style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${color};margin-left:5px;vertical-align:middle"></span>`;
  }
  // 정상(normal)은 배지 없이 비워둔다 — 대다수 그룹이 정상이라 표시하면 오히려 임박 배지가 묻힘
  return '';
}
function _isRenewalDue(group){
  const info = GROUP_CONTENT_URLS[group];
  return !!(info && info.renewalStatus && /^due_\d+d$/.test(info.renewalStatus));
}
